<?php
require_once __DIR__ . '/includes/functions.php'; if (session_status() !== PHP_SESSION_ACTIVE) session_start();
require_once __DIR__ . '/config/database.php';
$category = trim((string)($_GET['category'] ?? '')); $search = trim((string)($_GET['q'] ?? '')); $sort = (string)($_GET['sort'] ?? 'newest');
$allowedSort = ['newest'=>'id DESC','price_asc'=>'price ASC','price_desc'=>'price DESC','name'=>'name ASC'];
$where=[]; $params=[]; if ($category !== '') { $where[]='category = :category'; $params['category']=$category; } if ($search !== '') { $where[]='(name LIKE :q OR description LIKE :q)'; $params['q']='%'.$search.'%'; }
$sql='SELECT id,name,category,description,price,image,stock FROM products'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY '.($allowedSort[$sort]??$allowedSort['newest']);
$stmt=$pdo->prepare($sql);$stmt->execute($params);$products=$stmt->fetchAll();$categories=$pdo->query('SELECT DISTINCT category FROM products ORDER BY category')->fetchAll(PDO::FETCH_COLUMN);
$pageTitle='Өнімдер — Apple Store';require __DIR__.'/includes/header.php';
?>
<section class="page-intro"><p class="eyebrow">ӨНІМДЕР КАТАЛОГЫ</p><h1>Өзіңе лайық<br>технологияны таңда.</h1><p>Жұмысқа, оқуға және күнделікті өмірге арналған құрылғылар.</p></section>
<section class="catalog section-pad"><form class="filters" method="get"><label>Іздеу<input type="search" name="q" value="<?= e($search) ?>" placeholder="Өнім атауы"></label><label>Санат<select name="category"><option value="">Барлық санат</option><?php foreach($categories as $c): ?><option value="<?= e($c) ?>" <?= $category===$c?'selected':'' ?>><?= e($c) ?></option><?php endforeach; ?></select></label><label>Сұрыптау<select name="sort"><option value="newest" <?= $sort==='newest'?'selected':'' ?>>Жаңалары</option><option value="price_asc" <?= $sort==='price_asc'?'selected':'' ?>>Бағасы: төменнен жоғары</option><option value="price_desc" <?= $sort==='price_desc'?'selected':'' ?>>Бағасы: жоғарыдан төмен</option><option value="name" <?= $sort==='name'?'selected':'' ?>>Атауы</option></select></label><button class="button button-dark" type="submit">Қолдану</button></form>
<?php if (!$products): ?><div class="empty-state"><h2>Өнім табылмады</h2><p>Іздеу сөзін немесе сүзгіні өзгертіп көріңіз.</p><a class="text-link" href="products.php">Сүзгіні тазарту →</a></div><?php else: ?><p class="result-count"><?= count($products) ?> өнім</p><div class="product-grid"><?php foreach($products as $product): ?><article class="product-card"><a class="product-visual" href="product.php?id=<?= (int)$product['id'] ?>"><?= product_image($product) ?><span class="image-placeholder"></span></a><div class="product-info"><p class="eyebrow"><?= e($product['category']) ?></p><h3><a href="product.php?id=<?= (int)$product['id'] ?>"><?= e($product['name']) ?></a></h3><p class="product-desc"><?= e($product['description']) ?></p><div class="product-bottom"><strong><?= money($product['price']) ?></strong><a class="button button-small" href="product.php?id=<?= (int)$product['id'] ?>">Қарау</a></div></div></article><?php endforeach; ?></div><?php endif; ?></section>
